<?php require __DIR__.'/includes/bootstrap.php'; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$name=trim($_POST['name']);$mobile=preg_replace('/[^0-9]/','',$_POST['mobile']);$email=strtolower(trim($_POST['email']));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($_POST['password'])<8||$_POST['password']!==$_POST['confirm']){flash('Please provide valid details and matching passwords (8+ characters).','error');}else{try{$pdo->prepare("INSERT INTO customers(name,mobile,email,password_hash) VALUES(?,?,?,?)")->execute([$name,$mobile,$email,password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('Account created. Please log in.');redirect('login.php');}catch(PDOException $e){flash('An account with that email or mobile already exists.','error');}}}$pageTitle='Register';require __DIR__.'/includes/header.php'; ?>
<div class="auth-wrap"><form method="post" class="auth-card"><h1>Create your account</h1><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="field"><span>Full name</span><input name="name" required></label><div class="form-grid"><label class="field"><span>Mobile number</span><input name="mobile" pattern="[0-9+ -]{10,15}" required></label><label class="field"><span>Email</span><input type="email" name="email" required></label><label class="field"><span>Password</span><input type="password" name="password" minlength="8" required></label><label class="field"><span>Confirm password</span><input type="password" name="confirm" minlength="8" required></label></div><button class="btn btn-primary">Create account</button><p class="auth-alt">Already registered? <a href="login.php">Login</a></p></form></div><?php require __DIR__.'/includes/footer.php'; ?>